// Busca a lista de produtos antes de rodar o teste
pm.sendRequest({
    url: pm.environment.get("baseUrl") + "/products",
    method: 'GET'
}, function (err, res) {
    if (!err && res.code === 200) {
        const products = res.json();
        
        // Pega o ID do primeiro produto retornado na lista
        if (products.length > 0) {
            const dynamicId = products[0].id;
            
            // Define a variável temporária apenas para este teste
            pm.environment.set("productID", dynamicId);
            console.log("ID capturado dinamicamente:", dynamicId);
        }
    }
});

